SELECT sys.nick_name AS "keeperName", b.grid_id AS "gridId" FROM bm_gridkeeper a, bm_grid_keeper_ref b, sys_user sys WHERE a.keeper_id = b.keeper_id AND a.staff_id = sys.USER_ID and b.grid_id in
#{item}
AND a.delete_flag = 0 AND b.delete_flag = 0

SELECT u.USER_ID, u.USER_NAME, u.NICK_NAME, u.USER_TYPE, u.PHONENUMBER, u.tenant_id FROM sys_user u WHERE u.del_flag = '0'
and u.user_id in
#{userId}

SELECT u.USER_ID, u.USER_NAME, u.NICK_NAME, u.USER_TYPE, u.PHONENUMBER, u.tenant_id FROM sys_user u WHERE u.del_flag = '0'
and u.USER_NAME in
#{userName}
